(* [comment removed for export] *)
Lemma rdn_defined' : forall segs m (a : Z) (n : nat),
  (0 <= a)%Z -> (a + Z.of_nat n <= 2 ^ 64)%Z ->
  (forall i, (0 <= i < Z.of_nat n)%Z -> m (Z_to_bv 64 (a + i)) <> None) ->
  exists bs, rdn segs m (Z_to_bv 64 a) n = Some bs /\ length bs = n.
Proof.
