(* [comment removed for export] *)
Definition cmap_copy (C : lctx) (A A' : AS) (m' : word -> option byte) (cd ad : Z) (cv : cmapv) : Prop :=
  cmap_ok cv /\ (4096 <= cd)%Z /\ (cd + 32 <= alloc_top (c_vm C))%Z /\ (cd mod 16 = 0)%Z /\
  (4096 <= ad)%Z /\ (ad + 4 * c_nalloc cv <= alloc_top (c_vm C))%Z /\ (ad mod 16 = 0)%Z /\ cd <> ad /\
  live A (Z_to_bv 64 cd) = None /\ live A (Z_to_bv 64 ad) = None /\
  live (c_A0 C) (Z_to_bv 64 cd) = None /\ live (c_A0 C) (Z_to_bv 64 ad) = None /\
  live A' (Z_to_bv 64 cd) = Some 24%Z /\ live A' (Z_to_bv 64 ad) = Some (4 * c_nalloc cv)%Z /\
  (forall q, q <> Z_to_bv 64 cd -> q <> Z_to_bv 64 ad -> live A' q = live A q) /\
  CMAPat m' cd (CMAPV ad (c_d cv) (c_nalloc cv) (c_n cv) 0).


Theorem pixcmapCopy_W : forall C A m md regs (s cm : Z) (cv : cmapv) (ret : word) (S : TSet),
  Cok C -> W C A m md ->
  getr regs 2 = Z_to_bv 64 s -> (s mod 16 = 0)%Z -> (c_top C - LSTK + 48 + 16 + LSF <= s)%Z -> (s <= c_top C)%Z ->
  getr regs 1 = ret -> ret_ok ret -> getr regs 4 = Z_to_bv 64 0x49840 ->
  getr regs 10 = Z_to_bv 64 cm ->
  CMAPat m cm cv -> cmap_ok cv -> live A (Z_to_bv 64 cm) = Some 24%Z -> live A (Z_to_bv 64 (c_arr cv)) = Some (4 * c_nalloc cv)%Z ->
  forall (kR bR : Z), aroom A (m_vmmaps md) kR bR -> (RK_cmapcopy <= kR)%Z -> (RB_cmapcopy <= bR)%Z ->
  (forall A' m' vm' regs', W C A' m' (with_vmmaps vm' md) -> cs_kept regs regs' -> POSTM C A s m m' ->
     ( (getr regs' 10 = Z_to_bv 64 0 /\ forall q, live A' q = live A q)
       \/ (exists cd ad : Z, getr regs' 10 = Z_to_bv 64 cd /\ cmap_copy C A A' m' cd ad cv) ) ->
     aroom A' vm' (kR - RK_cmapcopy) (bR - RB_cmapcopy) ->
     realizes SEGS (mkCfg (mkst regs' ret m' al_rom) (with_vmmaps vm' md)) S) ->
